{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 찾은 병목이 개선 방법 선택으로 이어졌는지 확인한다. 신고 목록 조회 쿼리에 인덱스 추가와 조인 정리가 적절하다고 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리에 3.2초가 걸렸다.",
          "task": "실행 계획을 확인하고 조회 조건에 맞는 인덱스 추가와 조인 정리로 조회 시간을 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 전체 조인과 조회 조건이 인덱스 추가 및 조인 정리라는 선택으로 이어진 근거를 설명한다.",
          "result": "선택한 변경이 확인한 병목을 줄이는 데 적절했던 이유를 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 근거",
          "선택을 뒷받침한 실행 계획과 조회 조건",
          "확인한 병목과 선택한 변경 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨을 때, 인덱스 추가와 조인 정리를 택한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획이나 조회 조건에서 확인한 구체적인 문제를 인덱스 추가와 조인 정리의 선택 근거로 제시한다.",
            "선택한 변경이 불필요한 조회나 조인 부담을 줄이는 이유를 해당 쿼리의 병목과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가와 조인 정리를 선택한 이유를 제시하지만 실행 계획이나 조회 조건에 대한 설명이 일반적이다.",
            "선택한 변경과 병목의 관계를 설명하지만 일부 변경의 타당성을 뒷받침하는 내용이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "조회 시간이 줄었다는 결과나 변경 사항만 반복하고 선택 근거를 제시하지 못한다.",
            "실제 쿼리의 병목과 연결하지 못한 채 인덱스는 항상 빠르다는 식의 일반론이나 무관한 기술 설명에 머문다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 확인한 장애 원인이 재발 방지 판단으로 이어졌는지 확인한다. 잠금으로 오류를 고친 것과 별개로 배포 체크리스트에 스케줄러 항목을 넣은 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 간다는 문의가 들어왔다.",
          "task": "로그를 시간순으로 확인해 서버 두 대에서 스케줄러가 동시에 실행되는 것을 찾았고, 잠금 키를 두는 방식으로 수정한 뒤 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "로그에서 확인한 중복 실행 원인과 배포 체크리스트에 스케줄러 항목을 추가한 판단의 관계를 설명한다.",
          "result": "오류를 수정한 뒤에도 배포 단계에서 같은 위험을 확인할 필요가 있다고 판단한 근거를 설명한다."
        },
        "expectedEvidence": [
          "배포 체크리스트에 스케줄러 항목을 넣은 근거",
          "시간순 로그에서 확인한 서버 두 대의 스케줄러 동시 실행",
          "잠금 수정과 별도로 배포 점검이 필요하다고 본 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송을 로그로 추적하셨을 때, 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 서버 두 대의 스케줄러 동시 실행을 체크리스트 항목 추가의 구체적인 근거로 연결한다.",
            "잠금으로 오류를 수정한 것과 배포 때 같은 위험을 점검하는 것의 차이를 항목 추가의 이유 안에서 분명히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "같은 알림 중복 오류를 막으려는 취지로 체크리스트 항목을 추가했다고 답하지만 로그에서 확인한 원인과의 연결이 약하다.",
            "배포 점검이 필요했던 이유를 제시하지만 잠금 수정과 별도로 점검할 필요에 대한 설명이 포괄적이다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금으로 오류를 고쳤다는 내용만 설명하고 체크리스트 항목을 추가한 근거에는 답하지 못한다.",
            "로그에서 확인한 장애 원인과 관계없이 체크리스트가 중요하다는 일반론만 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업·사용자 요청을 요구사항 정의서로 구체화할 때 구현 범위를 합의할 수 있는지 평가한다. 요청의 목적에 비춰 개발 담당 팀원과 범위를 조정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "플랜업스쿨 서비스 기획 과정의 동네 세탁소 예약 서비스 기획 프로젝트에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 파악한 요청의 목적과 범위 조정의 근거를 연결해 설명한다.",
          "result": "설명한 근거가 요구사항 정의서에 포함하거나 제외할 범위를 정하는 데 어떤 차이를 만들었는지 설명한다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 요구사항 범위를 조정한 근거",
          "범위 판단의 근거가 된 세탁소 인터뷰의 요청이나 목적",
          "해당 근거와 요구사항의 포함·제외 또는 우선순위 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨을 때, 개발 담당 팀원과 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "한 가지 사례를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "범위를 조정한 근거를 세탁소 인터뷰에서 파악한 요청의 목적이나 필요성과 연결해 구체적으로 설명한다.",
            "그 근거에 따라 요구사항을 포함하거나 제외하거나 우선순위를 달리한 판단이 명확하고 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위를 조정한 근거를 제시하지만 사용자 요청이나 목적과의 연결이 일반적인 수준에 머문다.",
            "범위 선택의 방향은 설명하지만 해당 근거가 포함·제외 또는 우선순위에 미친 영향은 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다는 사실만 반복하고 범위를 조정한 근거를 설명하지 못한다.",
            "문서 작성 도구나 전달 방식 등 범위 판단과 무관한 내용으로 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름의 예외 상황을 화면 단위로 구체화할 수 있는지 평가한다. 예약·취소·알림의 예외 상황에서 화면이 취할 동작을 정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획 프로젝트에서 예약·취소·알림 흐름과 예외 상황을 다뤘다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서 28장을 작성했다.",
          "action": "직접 설계한 예외 상황을 짚고 해당 상황의 화면 동작을 정한 근거를 설명한다.",
          "result": "설명한 근거가 예외 상황의 화면 상태나 사용자 안내를 정하는 데 어떻게 연결됐는지 설명한다."
        },
        "expectedEvidence": [
          "예약·취소·알림의 예외 상황을 설계한 근거",
          "근거가 된 구체적인 예외 조건",
          "예외 조건과 화면 동작 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예약·취소·알림의 예외 상황을 설계한 근거는 무엇이었나요?",
      "answerTip": "듣는 사람이 떠올릴 수 있게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "직접 다룬 예외 조건을 구체적으로 짚고 그 조건에서 화면 동작을 정한 근거를 설명한다.",
            "제시한 근거가 예외 상황의 화면 상태나 안내와 일관되게 연결되어 구현할 동작을 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 설계한 근거를 제시하지만 조건이나 사용자 상황에 대한 설명이 일반적이다.",
            "근거와 화면 동작의 연결은 드러나지만 어떤 동작이 필요한지 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실만 반복하고 설계 판단의 근거를 설명하지 못한다.",
            "Figma 기능이나 화면의 시각적 취향 등 예외 상황의 동작과 무관한 내용으로 답한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량이 의심스러울 때 그대로 투약하지 않고 확인하는 판단을 검증한다. 평소의 두 배로 입력된 진통제 처방에서 투약을 멈추고 담당의에게 확인한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력되었다.",
          "task": "수술 전후 환자의 투약·처치를 담당했다.",
          "action": "처방 용량에서 어떤 점을 의심했고 왜 투약을 멈춰 담당의에게 확인했는지 설명한다.",
          "result": "처방의 의심이 해소되기 전에는 투약을 진행할 수 없다고 판단한 근거를 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인한 판단 근거",
          "처방 용량을 의심하게 된 비교 정보",
          "확인 전 투약 진행 여부를 판단할 때 고려한 환자 안전상의 위험"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈추고 담당의에게 확인하신 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 짚고 본인 경험을 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량을 의심한 근거를 평소 용량과의 차이 등 당시 확인한 정보로 구체적으로 설명한다.",
            "용량 차이만으로 처방 오류를 단정하지 않고, 확인 전 투약의 위험 때문에 중단하고 담당의에게 확인했다는 판단을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 용량이 커서 투약을 멈췄다고 답하지만 비교한 정보에 대한 설명이 제한적이다.",
            "의심스러운 처방은 담당의에게 확인해야 한다고 답하지만 당시 판단의 근거는 일반적인 안전 원칙에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "입력 오류였다는 결과만 반복하고 투약 전에 중단을 결정한 근거를 설명하지 못한다.",
            "의심이 남아 있어도 처방대로 투약하거나 임의로 용량을 바꾸면 된다는 설명으로 확인 절차를 대체한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰·기록한 환자 정보를 다음 근무자에게 빠짐없이 전달할 항목으로 연결하는 판단을 검증한다. 낙상 관련 사고 보고서에서 확인한 양상이 인수인계 항목 선정에 어떤 근거가 되었는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 QI 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "낙상 고위험 환자 인수인계 체크리스트 개선에 참여해 진통제 투여 시각과 보행 보조 여부를 항목으로 넣자고 제안했다.",
          "action": "사고 보고서에서 확인한 양상과 두 항목을 인수인계에 포함하자고 제안한 근거를 연결해 설명한다.",
          "result": "선정한 항목이 다음 근무자의 환자 상태 파악에 어떤 정보를 제공한다고 판단했는지 설명한다."
